steps.analogousExample:
/* Similar: media query for print */
@media print {
  /* Print-specific styles go here */
}

/* Similar: setting page properties for printing */
@page {
  size: A4;
  margin: 2cm;
}

/* Similar: forcing a new page before headings */
h2 {
  page-break-before: always;
}

/* Example of break-inside: auto */
.auto-break {
  break-inside: auto;
}

/* Similar: setting orphans and widows for paragraphs */
p {
  orphans: 2;
  widows: 2;
}

/* Testing print styles */
@media print {
  body {
    color: black;
    background: white;
  }
}
